// ============================================================
// LUX DOM DEMO - silnik narzedzi agenta
// Jeden Code node obsluguje wszystkie endpointy:
//   POST /webhook/luxdom/kontekst    <- conversation initiation (ElevenLabs)
//   POST /webhook/luxdom/zgloszenie
//   POST /webhook/luxdom/status
//   POST /webhook/luxdom/wizyta
//   POST /webhook/luxdom/dokument
//   POST /webhook/luxdom/sms
//   POST /webhook/luxdom/panel       <- podglad dla ekranu obok
// ============================================================

const KLUCZ = 'luxdom-demo-2026';           // <-- ten sam wpisz w naglowku X-Api-Key w ElevenLabs
const TELEFON_DYZURNEGO = '+48600000001';   // <-- PODMIEN: Twoja druga komorka
const TELEFON_BIURA = '+48222921915';

// ------------------------------------------------------------
// DANE DEMO
// ------------------------------------------------------------

const NIERUCHOMOSCI = {
  'sarmacka 12': {
    nazwa: 'Wspólnota Sarmacka 12',
    adresDoWymowienia: 'Sarmackiej dwanaście',
    administrator: 'Katarzyna Nowak',
    konto: '11 1020 1026 0000 0000 0000 0001',
  },
  'klimczaka 5': {
    nazwa: 'Wspólnota Klimczaka 5',
    adresDoWymowienia: 'Klimczaka pięć',
    administrator: 'Piotr Zieliński',
    konto: '11 1020 1026 0000 0000 0000 0002',
  },
};

// PODMIEN numery na telefony osob, ktore beda na spotkaniu.
const DZWONIACY = {
  '+48600100200': { imie: 'Marek Wiśniewski', salutation: 'panie Marku', formal: 'Pan', adres: 'Sarmacka 12', lokal: '34', rada: false },
  '+48600100201': { imie: 'Anna Kowalska', salutation: 'pani Anno', formal: 'Pani', adres: 'Klimczaka 5', lokal: '12', rada: true },
};

const TERMINY_DOKUMENTOW = {
  zaswiadczenie_o_niezaleganiu: 'do dwóch dni roboczych',
  uchwala: 'do trzech dni roboczych',
  protokol_zebrania: 'do trzech dni roboczych',
  plan_gospodarczy: 'do pięciu dni roboczych',
  sprawozdanie_finansowe: 'do pięciu dni roboczych',
  inne: 'do pięciu dni roboczych',
};

const SZABLONY_SMS = {
  potwierdzenie_zgloszenia: 'LUX DOM: zgloszenie nr {numer} przyjete. Status sprawdzisz w e-kartotece. Nie odpowiadaj na tego SMS-a.',
  potwierdzenie_wizyty: 'LUX DOM: wizyta {termin}, sprawa nr {numer}. Zmiana terminu: 22 292 19 15.',
  potwierdzenie_dokumentu: 'LUX DOM: zamowienie nr {numer} przyjete, termin {termin}.',
  dostep_do_ekartoteki: 'LUX DOM: e-kartoteka i instrukcja logowania: https://e-kartoteka.example.pl. Saldo i dokumenty po zalogowaniu.',
};

// ------------------------------------------------------------
// LICZBY I DATY DO WYMOWY
// ------------------------------------------------------------

const JED = ['zero', 'jeden', 'dwa', 'trzy', 'cztery', 'pięć', 'sześć', 'siedem', 'osiem', 'dziewięć'];
const NAS = ['dziesięć', 'jedenaście', 'dwanaście', 'trzynaście', 'czternaście', 'piętnaście', 'szesnaście', 'siedemnaście', 'osiemnaście', 'dziewiętnaście'];
const DZI = ['', '', 'dwadzieścia', 'trzydzieści', 'czterdzieści', 'pięćdziesiąt', 'sześćdziesiąt', 'siedemdziesiąt', 'osiemdziesiąt', 'dziewięćdziesiąt'];
const SET = ['', 'sto', 'dwieście', 'trzysta', 'czterysta', 'pięćset', 'sześćset', 'siedemset', 'osiemset', 'dziewięćset'];

const DNI = ['w niedzielę', 'w poniedziałek', 'we wtorek', 'w środę', 'w czwartek', 'w piątek', 'w sobotę'];
const MIESIACE = ['stycznia', 'lutego', 'marca', 'kwietnia', 'maja', 'czerwca', 'lipca', 'sierpnia', 'września', 'października', 'listopada', 'grudnia'];
const DZIEN = ['', 'pierwszego', 'drugiego', 'trzeciego', 'czwartego', 'piątego', 'szóstego', 'siódmego', 'ósmego', 'dziewiątego', 'dziesiątego',
  'jedenastego', 'dwunastego', 'trzynastego', 'czternastego', 'piętnastego', 'szesnastego', 'siedemnastego', 'osiemnastego', 'dziewiętnastego', 'dwudziestego',
  'dwudziestego pierwszego', 'dwudziestego drugiego', 'dwudziestego trzeciego', 'dwudziestego czwartego', 'dwudziestego piątego', 'dwudziestego szóstego',
  'dwudziestego siódmego', 'dwudziestego ósmego', 'dwudziestego dziewiątego', 'trzydziestego', 'trzydziestego pierwszego'];

const GODZINY = { '09:00': 'o dziewiątej rano', '11:30': 'o wpół do dwunastej', '13:30': 'o wpół do drugiej', '16:00': 'o szesnastej' };

function cyfry(x) {
  return String(x).replace(/\D/g, '').split('').map((d) => JED[Number(d)]).join(', ');
}

function pod1000(n) {
  const out = [];
  if (n >= 100) { out.push(SET[Math.floor(n / 100)]); n %= 100; }
  if (n >= 20) { out.push(DZI[Math.floor(n / 10)]); n %= 10; }
  else if (n >= 10) { out.push(NAS[n - 10]); n = 0; }
  if (n > 0) out.push(JED[n]);
  return out.join(' ');
}

function forma(n, jeden, dwa, piec) {
  if (n === 1) return jeden;
  const d = n % 10;
  const s = n % 100;
  if (d >= 2 && d <= 4 && !(s >= 12 && s <= 14)) return dwa;
  return piec;
}

function slownie(n) {
  if (n === 0) return 'zero';
  const tys = Math.floor(n / 1000);
  const reszta = n % 1000;
  const out = [];
  if (tys === 1) out.push('tysiąc');
  else if (tys > 1) out.push(pod1000(tys), forma(tys, 'tysiąc', 'tysiące', 'tysięcy'));
  if (reszta > 0) out.push(pod1000(reszta));
  return out.filter(Boolean).join(' ');
}

function kwota(v) {
  const zl = Math.floor(v);
  const gr = Math.round((v - zl) * 100);
  let out = slownie(zl) + ' ' + forma(zl, 'złoty', 'złote', 'złotych');
  if (gr > 0) out += ' i ' + slownie(gr) + ' ' + forma(gr, 'grosz', 'grosze', 'groszy');
  return out;
}

function dataSlownie(d) {
  return DNI[d.getDay()] + ', ' + DZIEN[d.getDate()] + ' ' + MIESIACE[d.getMonth()];
}

function godzinaSlownie(hhmm) {
  if (GODZINY[hhmm]) return GODZINY[hhmm];
  const [h, m] = hhmm.split(':').map(Number);
  return 'o ' + slownie(h) + (m ? ' ' + slownie(m) : '');
}

// ------------------------------------------------------------
// STAN (przezywa miedzy wywolaniami tego samego workflow)
// ------------------------------------------------------------

const stan = $getWorkflowStaticData('global');
if (!stan.zgloszenia) {
  stan.zgloszenia = [{
    numer: 4471,
    adres: 'Sarmacka 12',
    lokal: 'część wspólna',
    kategoria: 'ogrzewanie',
    opis: 'Awaria węzła cieplnego, brak ciepłej wody w budynku',
    priorytet: 'krytyczny',
    etap: 'w realizacji',
    ktoProwadzi: 'dyżurny technik',
    nastepnyKrok: 'wizyta technika dziś o dwudziestej drugiej trzydzieści',
    utworzono: new Date().toISOString(),
  }];
  stan.licznik = 4471;
  stan.smsy = [];
}

function normAdres(a) {
  return String(a || '').toLowerCase().replace(/\s*ul\.?\s*/g, '').replace(/\s+/g, ' ').trim();
}

function nieruchomosc(adres) {
  return NIERUCHOMOSCI[normAdres(adres)] || null;
}

function adresDoWymowienia(adres) {
  const n = nieruchomosc(adres);
  return n ? n.adresDoWymowienia : String(adres || '');
}

// ------------------------------------------------------------
// WEJSCIE
// ------------------------------------------------------------

const wejscie = $input.first().json;
const body = wejscie.body || {};
const naglowki = wejscie.headers || {};
const narzedzie = String((wejscie.params && wejscie.params.narzedzie) || body.narzedzie || '').toLowerCase();

function odp(o) { return [{ json: o }]; }
function blad(k) { return odp({ sukces: false, komunikat: k }); }

if ((naglowki['x-api-key'] || '') !== KLUCZ) {
  return blad('Nie mam w tej chwili dostępu do systemu. Przyjmę sprawę i przekażę ją do administratora.');
}

// ------------------------------------------------------------
// KONTEKST - dane do pierwszej wypowiedzi i zmiennych dynamicznych
// ------------------------------------------------------------

if (narzedzie === 'kontekst') {
  const numer = body.caller_id || body.system__caller_id || (body.call && body.call.from) || '';
  const kto = DZWONIACY[numer] || null;
  const teraz = new Date();
  const h = teraz.getHours();
  const wGodzinach = h >= 9 && h < 17 && teraz.getDay() >= 1 && teraz.getDay() <= 5;

  let otwarte = '';
  if (kto) {
    const moje = stan.zgloszenia.filter((z) => normAdres(z.adres) === normAdres(kto.adres) && z.etap !== 'zamknięte');
    if (moje.length) {
      const z = moje[0];
      otwarte = 'sprawa numer ' + cyfry(z.numer) + ', ' + z.opis + ', ' + z.nastepnyKrok;
    }
  }

  let pytanie = 'W czym mogę pomóc?';
  if (kto && kto.rada) pytanie = 'Łączę z opiekunem nieruchomości, chwileczkę.';
  else if (kto && otwarte) pytanie = 'Dzwoni ' + kto.formal + ' w sprawie awarii na ' + adresDoWymowienia(kto.adres) + '?';

  return odp({
    type: 'conversation_initiation_client_data',
    dynamic_variables: {
      caller_name: kto ? kto.imie : '',
      property_name: kto ? (nieruchomosc(kto.adres) || {}).nazwa || '' : '',
      property_address: kto ? adresDoWymowienia(kto.adres) : '',
      unit_number: kto ? kto.lokal : '',
      open_tickets: otwarte,
      current_time: dataSlownie(teraz) + ', godzina ' + teraz.getHours() + ':' + String(teraz.getMinutes()).padStart(2, '0'),
      office_hours: 'poniedziałek do piątku, od dziewiątej do siedemnastej',
      is_office_hours: wGodzinach ? 'tak' : 'nie',
      greeting: h >= 18 || h < 4 ? 'Dobry wieczór' : 'Dzień dobry',
      caller_salutation: kto ? ' ' + kto.salutation : '',
      opening_question: pytanie,
    },
  });
}

// ------------------------------------------------------------
// ZGLOSZENIE
// ------------------------------------------------------------

if (narzedzie === 'zgloszenie') {
  const adres = body.adres;
  const lokal = body.numer_lokalu;
  const kategoria = body.kategoria || 'inne';
  const priorytet = body.priorytet === 'krytyczny' ? 'krytyczny' : 'zwykly';

  if (!adres || !lokal) {
    return blad('Zanim zapiszę zgłoszenie, potrzebuję adresu i numeru lokalu.');
  }

  const doba = Date.now() - 24 * 60 * 60 * 1000;
  const duplikat = stan.zgloszenia.find((z) =>
    normAdres(z.adres) === normAdres(adres) &&
    z.kategoria === kategoria &&
    z.etap !== 'zamknięte' &&
    new Date(z.utworzono).getTime() > doba);

  if (duplikat) {
    return odp({
      sukces: true,
      duplikat: true,
      numer_sprawy: String(duplikat.numer),
      numer_sprawy_do_wymowienia: cyfry(duplikat.numer),
      eskalacja: false,
      komunikat: 'Ta awaria jest już zgłoszona pod numerem ' + cyfry(duplikat.numer) +
        '. ' + duplikat.nastepnyKrok.charAt(0).toUpperCase() + duplikat.nastepnyKrok.slice(1) +
        '. Dopisałam Państwa do sprawy i wyślemy powiadomienie po naprawie.',
    });
  }

  stan.licznik += 1;
  const nowe = {
    numer: stan.licznik,
    adres: adres,
    lokal: lokal,
    kategoria: kategoria,
    opis: body.opis || '',
    priorytet: priorytet,
    etap: priorytet === 'krytyczny' ? 'eskalowane do dyżurnego' : 'przyjęte',
    ktoProwadzi: priorytet === 'krytyczny' ? 'dyżurny technik' : (nieruchomosc(adres) || {}).administrator || 'administrator nieruchomości',
    nastepnyKrok: priorytet === 'krytyczny' ? 'dyżurny technik jest powiadamiany' : 'administrator odezwie się w dzień roboczy',
    dostep: body.dostep_do_lokalu || '',
    zglaszajacy: body.imie_zglaszajacego || '',
    telefon: body.telefon || '',
    idRozmowy: body.id_rozmowy || '',
    utworzono: new Date().toISOString(),
  };
  stan.zgloszenia.unshift(nowe);

  const komunikat = priorytet === 'krytyczny'
    ? 'Zgłoszenie przyjęte jako awaria, numer sprawy ' + cyfry(nowe.numer) + '. Łączę z dyżurnym technikiem, proszę się nie rozłączać.'
    : 'Zgłoszenie przyjęte, numer sprawy ' + cyfry(nowe.numer) + '. Przekazuję je do administratora nieruchomości.';

  return odp({
    sukces: true,
    duplikat: false,
    numer_sprawy: String(nowe.numer),
    numer_sprawy_do_wymowienia: cyfry(nowe.numer),
    eskalacja: priorytet === 'krytyczny',
    telefon_dyzurnego: priorytet === 'krytyczny' ? TELEFON_DYZURNEGO : '',
    komunikat: komunikat,
  });
}

// ------------------------------------------------------------
// STATUS
// ------------------------------------------------------------

if (narzedzie === 'status') {
  let z = null;
  if (body.numer_sprawy) {
    const n = Number(String(body.numer_sprawy).replace(/\D/g, ''));
    z = stan.zgloszenia.find((x) => x.numer === n) || null;
  }
  if (!z && body.adres) {
    z = stan.zgloszenia.find((x) => normAdres(x.adres) === normAdres(body.adres) && x.etap !== 'zamknięte') || null;
  }
  if (!z) {
    return odp({ sukces: true, znaleziono: false, komunikat: 'Nie widzę takiej sprawy w systemie. Mogę przyjąć nowe zgłoszenie.' });
  }
  return odp({
    sukces: true,
    znaleziono: true,
    numer_sprawy_do_wymowienia: cyfry(z.numer),
    etap: z.etap,
    kto_prowadzi: z.ktoProwadzi,
    nastepny_krok: z.nastepnyKrok,
    komunikat: 'Sprawa ' + cyfry(z.numer) + ' ma status: ' + z.etap + '. ' +
      z.nastepnyKrok.charAt(0).toUpperCase() + z.nastepnyKrok.slice(1) + '.',
  });
}

// ------------------------------------------------------------
// WIZYTA
// ------------------------------------------------------------

if (narzedzie === 'wizyta') {
  const akcja = body.akcja === 'potwierdz' ? 'potwierdz' : 'pobierz_terminy';

  if (akcja === 'pobierz_terminy') {
    const terminy = [];
    const d = new Date();
    const godziny = ['09:00', '13:30'];
    let i = 0;
    while (terminy.length < 2) {
      d.setDate(d.getDate() + 1);
      if (d.getDay() === 0 || d.getDay() === 6) continue;
      const g = godziny[i % godziny.length];
      terminy.push({
        id: 't' + (terminy.length + 1),
        data: d.toISOString().slice(0, 10),
        godzina: g,
        opis_do_wymowienia: dataSlownie(d) + ', ' + godzinaSlownie(g),
      });
      i += 1;
    }
    stan.terminy = terminy;
    return odp({
      sukces: true,
      terminy: terminy,
      komunikat: 'Mam dwa terminy: ' + terminy[0].opis_do_wymowienia + ', albo ' + terminy[1].opis_do_wymowienia + '. Który pasuje?',
    });
  }

  const wybrany = (stan.terminy || []).find((t) => t.id === body.id_terminu) || (stan.terminy || [])[0];
  if (!wybrany) {
    return blad('Nie mam zapamiętanych terminów. Sprawdzę je jeszcze raz.');
  }
  return odp({
    sukces: true,
    termin_do_wymowienia: wybrany.opis_do_wymowienia,
    komunikat: 'Zapisane, ' + wybrany.opis_do_wymowienia + '. Wyślę potwierdzenie SMS-em.',
  });
}

// ------------------------------------------------------------
// DOKUMENT
// ------------------------------------------------------------

if (narzedzie === 'dokument') {
  const typ = body.typ_dokumentu || 'inne';
  const rola = body.rola_zamawiajacego || 'inna';
  const termin = TERMINY_DOKUMENTOW[typ] || TERMINY_DOKUMENTOW.inne;
  const zgoda = rola !== 'wlasciciel';

  stan.licznik += 1;
  const numer = stan.licznik;

  let komunikat = 'Zamówienie przyjęte, numer ' + cyfry(numer) + '. Dokument przygotujemy ' + termin + '.';
  if (zgoda) {
    komunikat += ' Ponieważ zamawiającym nie jest właściciel lokalu, księgowość poprosi właściciela o zgodę na przekazanie danych.';
  }

  return odp({
    sukces: true,
    numer_zlecenia: String(numer),
    numer_zlecenia_do_wymowienia: cyfry(numer),
    termin_do_wymowienia: termin,
    wymaga_zgody_wlasciciela: zgoda,
    komunikat: komunikat,
  });
}

// ------------------------------------------------------------
// SMS
// ------------------------------------------------------------

if (narzedzie === 'sms') {
  const szablon = SZABLONY_SMS[body.szablon];
  if (!szablon) {
    return blad('Nie mam takiego szablonu wiadomości.');
  }
  const tresc = szablon
    .replace('{numer}', String(body.numer_sprawy || '').replace(/\D/g, ''))
    .replace('{termin}', body.termin || '');

  stan.smsy.unshift({ numer: body.numer_telefonu || '', tresc: tresc, kiedy: new Date().toISOString() });

  return odp({
    sukces: true,
    wyslano: true,
    tresc: tresc,
    komunikat: 'Potwierdzenie wysłałam SMS-em.',
  });
}

// ------------------------------------------------------------
// PANEL (ekran obok, nie narzedzie agenta)
// ------------------------------------------------------------

if (narzedzie === 'panel') {
  return odp({ sukces: true, zgloszenia: stan.zgloszenia.slice(0, 25), smsy: stan.smsy.slice(0, 10) });
}

return blad('Nieznane narzędzie: ' + narzedzie);
